import type { Meta, StoryObj } from "@storybook/react-vite"
import { createStorybookDecorator } from "@/config/StorybookDecorator"
import ContextWindow from "./ContextWindow"

const meta: Meta<typeof ContextWindow> = {
	title: "Views/Components/ContextWindow",
	component: ContextWindow,
	parameters: {
		layout: "padded",
		docs: {
			description: {
				component:
					"ContextWindow shows token usage against the model's context window and hosts the compact-task button with its inline confirmation card. The decorator mimics the expanded TaskHeader card so spacing and contrast are representative.",
			},
		},
	},
	decorators: [
		createStorybookDecorator(
			undefined,
			// Mirror TaskHeader's expanded card surface so the compact
			// confirmation is previewed against its real background.
			"rounded-sm border-1 pt-2 pb-2 px-2 bg-(--vscode-toolbar-hoverBackground)/65",
		),
	],
	argTypes: {
		contextWindow: { control: "number", description: "Model context window size" },
		lastApiReqTotalTokens: { control: "number", description: "Tokens used by the last request" },
	},
}

export default meta
type Story = StoryObj<typeof ContextWindow>

export const HighUsage: Story = {
	args: {
		contextWindow: 200_000,
		lastApiReqTotalTokens: 146_000,
		tokensIn: 45_000,
		tokensOut: 28_000,
		cacheWrites: 5_200,
		cacheReads: 3_800,
		useAutoCondense: false,
	},
	parameters: {
		docs: {
			description: {
				story: "High context usage. Click the fold icon to open the compact-task confirmation card.",
			},
		},
	},
}

import { StringRequest } from "@shared/proto/cline/common"
import { VSCodeButton } from "@vscode/webview-ui-toolkit/react"
import debounce from "debounce"
import React, { memo, useCallback, useEffect, useMemo, useRef, useState } from "react"
import { HoverCard, HoverCardContent, HoverCardTrigger } from "@/components/ui/hover-card"
import { Progress } from "@/components/ui/progress"
import { SlashServiceClient } from "@/services/grpc-client"
import { formatLargeNumber as formatTokenNumber } from "@/utils/format"
import CompactTaskButton from "./buttons/CompactTaskButton"
import { ContextWindowSummary } from "./ContextWindowSummary"

// Type definitions
interface ContextWindowInfoProps {
	tokensIn?: number
	tokensOut?: number
	cacheWrites?: number
	cacheReads?: number
	size?: number
}

interface ContextWindowProgressProps extends ContextWindowInfoProps {
	useAutoCondense: boolean
	lastApiReqTotalTokens?: number
	contextWindow?: number
	onSendMessage?: (command: string, files: string[], images: string[]) => void
}

const ConfirmationDialog = memo<{
	onConfirm: (e: React.MouseEvent) => void
	onCancel: (e: React.MouseEvent) => void
}>(({ onConfirm, onCancel }) => (
	<div className="mt-2 flex flex-col gap-2 rounded-sm border border-border-panel bg-code p-2 text-sm">
		<span className="font-semibold">Compact the current task?</span>
		<span className="text-xs text-description">
			Replaces the conversation history with a summary to free up context window space.
		</span>
		<span className="flex justify-end gap-1.5">
			<VSCodeButton
				appearance="secondary"
				className="text-sm"
				onClick={onCancel}
				title="No, keep the task as is"
				type="button">
				Cancel
			</VSCodeButton>
			<VSCodeButton
				appearance="primary"
				autoFocus={true}
				className="text-sm"
				onClick={onConfirm}
				title="Yes, compact the task"
				type="button">
				Compact
			</VSCodeButton>
		</span>
	</div>
))
ConfirmationDialog.displayName = "ConfirmationDialog"

const ContextWindow: React.FC<ContextWindowProgressProps> = ({
	contextWindow = 0,
	lastApiReqTotalTokens = 0,
	onSendMessage,
	useAutoCondense,
	tokensIn,
	tokensOut,
	cacheWrites,
	cacheReads,
}) => {
	const [isOpened, setIsOpened] = useState(false)
	const [confirmationNeeded, setConfirmationNeeded] = useState(false)
	const progressBarRef = useRef<HTMLDivElement>(null)

	const handleCompactClick = useCallback(
		(e: React.MouseEvent) => {
			e.preventDefault()
			e.stopPropagation()
			setConfirmationNeeded(!confirmationNeeded)
		},
		[confirmationNeeded],
	)

	const handleConfirm = useCallback((e: React.MouseEvent) => {
		e.preventDefault()
		e.stopPropagation()
		// Trigger a real SDK manual compaction rather than sending the literal
		// text "/compact" to the model (which it would treat as a normal prompt
		// and improvise a fake summary — CLINE-2503). The condense RPC runs the
		// same SDK compaction effect as the CLI's `/compact` command.
		SlashServiceClient.condense(StringRequest.create({ value: "compact" })).catch((err) =>
			console.error("Failed to compact task:", err),
		)
		setConfirmationNeeded(false)
	}, [])

	const handleCancel = useCallback((e: React.MouseEvent) => {
		e.preventDefault()
		e.stopPropagation()
		setConfirmationNeeded(false)
	}, [])

	const tokenData = useMemo(() => {
		if (!contextWindow) {
			return null
		}
		return {
			percentage: (lastApiReqTotalTokens / contextWindow) * 100,
			max: contextWindow,
			used: lastApiReqTotalTokens,
		}
	}, [contextWindow, lastApiReqTotalTokens])

	const debounceCloseHover = useCallback((e: React.MouseEvent) => {
		e.preventDefault()
		e.stopPropagation()
		const showHover = debounce((open: boolean) => setIsOpened(open), 100)

		return showHover(false)
	}, [])

	const handleFocus = useCallback(() => {
		setIsOpened(true)
	}, [])

	// Close tooltip when clicking outside
	useEffect(() => {
		const handleClickOutside = (event: MouseEvent) => {
			const target = event.target as Element
			const isInsideProgressBar = progressBarRef.current?.contains(target as Node)

			// Check if click is inside any tooltip content by looking for our custom class
			const isInsideTooltipContent = target.closest(".context-window-tooltip-content") !== null

			if (!isInsideProgressBar && !isInsideTooltipContent) {
				setIsOpened(false)
			}
		}

		if (isOpened) {
			document.addEventListener("mousedown", handleClickOutside)
			return () => document.removeEventListener("mousedown", handleClickOutside)
		}
	}, [isOpened])

	if (!tokenData) {
		return null
	}

	return (
		<div className="flex flex-col mt-1.5" onMouseLeave={debounceCloseHover}>
			<div className="flex gap-1 flex-row @max-xs:flex-col @max-xs:items-start items-center text-sm">
				<div className="flex items-center gap-1.5 flex-1 whitespace-nowrap">
					<span className="cursor-pointer text-sm" title="Current tokens used in this request">
						{formatTokenNumber(tokenData.used)}
					</span>
					<div className="flex relative items-center gap-1 flex-1 w-full h-full" onMouseEnter={() => setIsOpened(true)}>
						<HoverCard>
							<HoverCardContent className="bg-menu rounded-xs shadow-sm">
								<ContextWindowSummary
									cacheReads={cacheReads}
									cacheWrites={cacheWrites}
									contextWindow={tokenData.max}
									percentage={tokenData.percentage}
									tokensIn={tokensIn}
									tokensOut={tokensOut}
									tokenUsed={tokenData.used}
								/>
							</HoverCardContent>
							<HoverCardTrigger asChild>
								{/* TODO: Re-add role="slider", aria-value*, onKeyDown, onClick, and tabIndex
								    when click-to-set-threshold is implemented. See PR #9348 for context. */}
								<div
									className="relative w-full text-foreground context-window-progress brightness-100"
									onFocus={handleFocus}
									ref={progressBarRef}>
									<Progress
										aria-label="Context window usage progress"
										color="success"
										value={tokenData.percentage}
									/>
									{isOpened}
								</div>
							</HoverCardTrigger>
						</HoverCard>
					</div>
					<span className="cursor-pointer text-sm" title="Maximum context window size for this model">
						{formatTokenNumber(tokenData.max)}
					</span>
				</div>
				<CompactTaskButton onClick={handleCompactClick} />
			</div>
			{confirmationNeeded && <ConfirmationDialog onCancel={handleCancel} onConfirm={handleConfirm} />}
		</div>
	)
}

export default memo(ContextWindow)

import { toModelSpec } from "../provider-models/bundled-references";
import type { Model } from "../types";
import { resolveModelPolicy } from "./resolve";

/**
 * Rule-owned maxima by provider/id/api. Resolve once per process rather than
 * walking the static policy cascade on every catalog rebuild. Null caches the
 * absence of a curated maximum; undefined means the key has not been resolved.
 * Bounded: one entry per distinct model; the wire-id set is bounded.
 */
const ruleMaximumCache = new Map<string, number | null>();
const clampOverrideCache = new Map<string, boolean>();
const RULE_POLICY_CACHE_MAX = 8192;

/**
 * Extended-context capacity. Curated maxima correct stale lower discovery
 * values; a higher live maximum still wins. The registry applies this capacity
 * only when extended context is enabled, before explicit user overrides.
 */
export function resolveMaxContextWindow(model: Model): number | undefined {
	const key = `${model.provider} ${model.id} ${model.api}`;
	let curated = ruleMaximumCache.get(key);
	if (curated === undefined) {
		const maximum = resolveModelPolicy(toModelSpec(model)).catalog.maxContextWindow;
		curated = typeof maximum === "number" && Number.isFinite(maximum) && maximum > 0 ? maximum : null;
		if (ruleMaximumCache.size >= RULE_POLICY_CACHE_MAX) ruleMaximumCache.clear();
		ruleMaximumCache.set(key, curated);
	}

	const maximum = model.maxContextWindow;
	if (typeof maximum === "number" && Number.isFinite(maximum) && maximum > 0) {
		return Math.max(maximum, curated ?? 0);
	}
	return curated ?? undefined;
}

/**
 * Override ceiling for Codex models. Upstream clamps `model_context_window`
 * to `min(override, max_context_window)` (`with_config_overrides` in
 * `models-manager/src/model_info.rs`); the ceiling here is stale-aware — the
 * curated maximum corrects a lower server value (Astra reports a stale 872K
 * maximum; OpenAI documents at most 922K input) while a higher live maximum
 * still wins. No curated or live maximum means no ceiling: overrides pass
 * through, matching upstream's unclamped branch.
 */
export function codexOverrideCeiling(model: Model): number | undefined {
	return resolveMaxContextWindow(model);
}

/**
 * Whether explicit context-window overrides for this model clamp to the
 * server-honored ceiling. KDL-owned (`clamp-context-override`): branching on
 * it here keeps provider deployment contracts out of TypeScript.
 */
export function clampsContextOverride(model: Model): boolean {
	const key = `${model.provider} ${model.id} ${model.api}`;
	const cached = clampOverrideCache.get(key);
	if (cached !== undefined) return cached;
	const clamps = resolveModelPolicy(toModelSpec(model)).catalog.clampContextOverride === true;
	if (clampOverrideCache.size >= RULE_POLICY_CACHE_MAX) clampOverrideCache.clear();
	clampOverrideCache.set(key, clamps);
	return clamps;
}

/**
 * Clamp a requested Codex context window to the override ceiling, mirroring
 * upstream. `model` is the pre-override model: the ceiling never shrinks the
 * request below the window that already works, so a stale-low live maximum
 * (e.g. 128K base with a 64K advertised maximum) cannot punish an explicit
 * override. Returns the request unchanged when no ceiling applies or it
 * already fits.
 */
export function clampCodexContextWindow(model: Model, requested: number): number {
	if (!Number.isFinite(requested) || requested <= 0) {
		return requested;
	}
	const ceiling = codexOverrideCeiling(model);
	if (ceiling === undefined || requested <= ceiling) {
		return requested;
	}
	const current = model.contextWindow;
	const floor = typeof current === "number" && Number.isFinite(current) && current > 0 ? current : 0;
	return Math.min(requested, Math.max(ceiling, floor));
}

